#include "../../include/compiler/compileRegistry.h"
#include "../../include/compiler/compiler.h"

#include <iostream>
#include <sstream>
#include <fstream>
#include <filesystem>
#include <unordered_set>

#include "common/loopUltil.h"
#include "common/utility.h"
#include "compiler/compileCondition.h"
#include "compiler/compileLoop.h"
#include "compiler/compilerExpr.h"
#include "compiler/compileSwitch.h"
#include "common/storeString.h"
#include "compiler/compileBlock.h"

std::unordered_map<std::string, CompileFunc> compileMap;

namespace vietvm { namespace compiler {
    std::unordered_set<std::string> importedFiles;
    void clearImportedFiles() { importedFiles.clear(); }
} }

static std::vector<std::string> splitArgs(const std::string &s) {
    std::vector<std::string> res;
    std::string cur;
    int depth = 0;
    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c == '(') { depth++; cur.push_back(c); }
        else if (c == ')') { depth--; cur.push_back(c); }
        else if (c == ',' && depth == 0) {
            res.push_back(cur);
            cur.clear();
        } else {
            cur.push_back(c);
        }
    }
    if (!cur.empty()) res.push_back(cur);
    // trim spaces
    for (auto &t : res) {
        // simple trim
        size_t a = t.find_first_not_of(" \t\n\r");
        size_t b = t.find_last_not_of(" \t\n\r");
        if (a == std::string::npos) t = "";
        else t = t.substr(a, b - a + 1);
    }
    return res;
}

void initCompileMap() {
    compileMap["in"]  = [](const std::vector<std::string>& tokens, size_t &pos,
                           std::vector<Instruction>& bytecode,
                           std::unordered_map<std::string,int>& symTab,
                           int& nextId,
                           const std::unordered_map<std::string,Opcode>& keywordMap) {
                                ++pos; // bỏ qua "in"
                                auto pr = vietvm::compiler::extractExpressionUntilSemicolon(tokens, pos);
                                compileExpr(pr.first, bytecode, symTab, nextId, keywordMap);
                                bytecode.push_back({OP_IN, 0, 0,0});
                                pos = pr.second;
    };

    compileMap["nếu"] = compileCondition;
    compileMap["lặp"] = [](const std::vector<std::string>& tokens, size_t &pos,
                       std::vector<Instruction>& bytecode,
                       std::unordered_map<std::string,int>& symTab,
                       int& nextId,
                       const std::unordered_map<std::string,Opcode>& keywordMap) {
                            if (tokens[pos] == "lặp") {
                                std::string loopHeader = vietvm::compiler::extractParens(tokens, pos + 1).first;
                                std::vector<std::string> parts = splitLoopParts(loopHeader);
                                std::string varName = vietvm::compiler::extractAssignedVar(parts[0]);
                                if (!varName.empty()) {
                                    if (symTab.find(varName) == symTab.end()) {
                                        symTab[varName] = nextId++;
                                    }
                                    int varId = symTab[varName];
                                    bytecode.push_back({OP_KHOI_TAO, varId, 0,0});
                                }
                                compileLoop(tokens, pos, bytecode, symTab, nextId, keywordMap);
                            }
                       };
    compileMap["chọn"] = compileSwitch;

    // Handler "hàm" (robust pos handling)
    compileMap["hàm"] = [](const std::vector<std::string>& tokens, size_t &pos,
                           std::vector<Instruction>& bytecode,
                           std::unordered_map<std::string,int>& symTab,
                           int& nextId,
                           const std::unordered_map<std::string,Opcode>& keywordMap) {
        ++pos; // skip 'hàm'
        if (pos >= tokens.size()) throw std::runtime_error("compile: thiếu tên hàm sau 'hàm'");
        std::string fname = tokens[pos++];
        int nameIndex = vietvm::compiler::StringPool::storeString(fname);

        // assign function id
        int hamId = vietvm::compiler::hamMap::allocHamId();
        symTab[fname] = hamId;

        // parse parameter list if present
        std::vector<std::string> params;
        if (pos < tokens.size() && tokens[pos] == "(") {
            auto pr = vietvm::compiler::extractParens(tokens, pos);
            // extractParens should return pair<inside, newPos>
            std::string inside = pr.first;
            pos = pr.second;
            // split args
            std::stringstream ss(inside);
            std::string item;
            while (std::getline(ss, item, ',')) {
                size_t a = item.find_first_not_of(" \t\n\r");
                size_t b = item.find_last_not_of(" \t\n\r");
                if (a != std::string::npos) params.push_back(item.substr(a, b - a + 1));
            }
        }

        // Now pos should be at the next token after params. Expect '{'
        if (pos >= tokens.size() || tokens[pos] != "{") {
            throw std::runtime_error(std::string("compileBlock: expected '{' at pos=") + std::to_string(pos)
                                     + ", found token='" + (pos < tokens.size() ? tokens[pos] : "EOF") + "'");
        }

        // compile function body into temporary vector
        std::vector<Instruction> funcCode;
        funcCode.push_back({OP_MO_KHOI, 0, 0, 0});

        // emit OP_PARAM prologue
        for (size_t i = 0; i < params.size(); ++i) {
            const std::string &pname = params[i];
            if (pname.empty()) continue;
            if (symTab.find(pname) == symTab.end()) symTab[pname] = nextId++;
            int varId = symTab[pname];
            funcCode.push_back({OP_KHOI_TAO, 0, varId, 0});
            funcCode.push_back({OP_PARAM, 0, varId, (int)i});
        }
        // Let compileBlock consume until matching '}' — compileBlock must update pos to point after '}'
        compileBlock(tokens, pos, funcCode, symTab, nextId, keywordMap);

        // ensure compileBlock left pos at token after '}', if not adjust as needed
        // function epilogue
        funcCode.push_back({OP_DONG_KHOI, 0, 0, 0});
        funcCode.push_back({OP_DONG_LENH, 0, 0, 0});

        // store function code
        vietvm::compiler::hamMap::hamBytecodeMap[hamId] = std::move(funcCode);
        vietvm::compiler::hamMap::setHamNameIndex(hamId, nameIndex);

        // Optionally emit an OP_HAM marker into outer bytecode for discovery
        bytecode.push_back({OP_HAM, nameIndex , hamId, 0});
    };

    // ---- Handler: gọi hàm bằng từ khóa 'gọi' ----
    // cú pháp: gọi <tên>(arg1, arg2, ...)
    // ---- Handler: gọi hàm bằng từ khóa 'gọi' ----
    compileMap["gọi"] = [](const std::vector<std::string>& tokens, size_t &pos,
                           std::vector<Instruction>& bytecode,
                           std::unordered_map<std::string,int>& symTab,
                           int& nextId,
                           const std::unordered_map<std::string,Opcode>& keywordMap) {
        ++pos;
        if (pos >= tokens.size()) throw std::runtime_error("gọi: thiếu tên hàm");
        std::string fname = tokens[pos++];

        // resolve function id from symTab (must have been set when compiling declaration)
        int hamId = -1;
        auto itSym = symTab.find(fname);
        if (itSym != symTab.end()) {
            hamId = itSym->second;
        } else {
            // fallback: store name in string pool and emit OP_GOI with nameIndex (VM fallback will try resolve)
            hamId = -1;
        }

        // parse args
        if (pos >= tokens.size() || tokens[pos] != "(") throw std::runtime_error("gọi: thiếu '(' sau tên hàm");
        auto pr = vietvm::compiler::extractParens(tokens, pos);
        std::string inside = pr.first;
        pos = pr.second;

        std::vector<std::string> args = splitArgs(inside);
        int compiledArgs = 0;
        for (const auto &aexpr : args) {
            if (aexpr.empty()) continue;
            compileExpr(aexpr, bytecode, symTab, nextId, keywordMap);
            ++compiledArgs;
        }

        if (hamId >= 0) {
            // emit with hamId in operand and argc in operandIndex
            bytecode.push_back({OP_GOI, compiledArgs, hamId, 0});
        } else {
            // fallback: emit with nameIndex so VM fallback can resolve (less ideal)
            int nameIndex = vietvm::compiler::StringPool::storeString(fname);
            bytecode.push_back({OP_GOI, compiledArgs, nameIndex, 0});
        }

        if (pos < tokens.size() && tokens[pos] == ";") ++pos;
    };

    // ---- Handler: nhập (import modules/files) ----
    // Syntax (MVP):
    //   nhập "path/to/module.vi";
    //   nhập moduleName;    // resolves to moduleName.vi in cwd
    compileMap["nhập"] = [](const std::vector<std::string>& tokens, size_t &pos,
                             std::vector<Instruction>& bytecode,
                             std::unordered_map<std::string,int>& symTab,
                             int& nextId,
                             const std::unordered_map<std::string,Opcode>& keywordMap) {
        // These parameters are required by CompileFunc signature but not used by nhập
        // because import only causes side-effects (registering functions/strings)
        (void)bytecode;
        (void)symTab;
        (void)nextId;

        ++pos; // skip 'nhập'
        if (pos >= tokens.size()) throw std::runtime_error("nhập: thiếu đường dẫn hoặc tên module");
        std::string target = tokens[pos++];

        // optional semicolon will be consumed later

        // Determine path
        std::string path;
        if (target.size() >= 2 && (target.front() == '"' || target.front() == '\'')) {
            // strip quotes (no escape processing here)
            path = target.substr(1, target.size() - 2);
        } else {
            // treat identifier as file name with .vi
            path = target + ".vi";
        }

        namespace fs = std::filesystem;
        fs::path p(path);
        // Make absolute and normalized path (if possible)
        fs::path abs;
        try {
            abs = fs::absolute(p).lexically_normal();
        } catch (...) {
            abs = p;
        }

        // If resolved path does not exist, attempt to locate the file by searching
        // upward from the current working directory and appending the requested path.
        // This helps with imports like "src/tests/..." when the process cwd is build/bin.
        if (!fs::exists(abs)) {
            for (fs::path dir = fs::current_path(); ; dir = dir.parent_path()) {
                fs::path cand = dir / p;
                if (fs::exists(cand)) {
                    abs = fs::absolute(cand).lexically_normal();
                    break;
                }
                if (dir == dir.parent_path()) break; // reached filesystem root
            }
        }

        std::string canonical = abs.string();

        if (vietvm::compiler::importedFiles.find(canonical) != vietvm::compiler::importedFiles.end()) {
            // already imported in this compile session — no-op
            if (pos < tokens.size() && tokens[pos] == ";") ++pos;
            return;
        }

        // Mark as in-progress before reading/compiling to prevent circular imports
        vietvm::compiler::importedFiles.insert(canonical);

        try {
            // read file
            std::ifstream ifs(canonical);
            if (!ifs.is_open()) {
                throw std::runtime_error(std::string("nhập: không thể mở file '") + canonical + "'");
            }
            std::stringstream ss;
            ss << ifs.rdbuf();
            std::string src = ss.str();

            // Compile the module for its registration side effects only.
            // Imported functions/strings are recorded in the global registries;
            // the returned module bytecode is not merged or executed here.
            (void)compileSource(src, keywordMap, false);
        } catch (...) {
            // Rollback on failure
            vietvm::compiler::importedFiles.erase(canonical);
            throw;
        }

        if (pos < tokens.size() && tokens[pos] == ";") ++pos;
    };
}

// Created by nx_thang on 10/20/2025.
// Updated: bổ sung hỗ trợ comment, escape trong string, cải thiện nhận diện identifier UTF-8,
// and ổn định post-processing multi-word keywords.
// Updated: thêm error handling và exception cho các trường hợp ngoài mong đợi.

#include <algorithm>
#include <cctype>
#include <sstream>
#include <stdexcept>
#include <variant>
#include <string>
#include <unordered_map>

#include "../../include/frontend/lexer.h"
#include "common/utility.h"

namespace vietvm::compiler {
    using Value = std::variant<int, std::string>;
    std::vector<Value> vars; // indexed by varId

    // ==================== Helper Functions Implementation ====================

    std::pair<size_t, size_t> getLineAndColumn(const std::string& src, size_t index) {
        size_t line = 1;
        size_t col = 1;
        for (size_t i = 0; i < index && i < src.size(); ++i) {
            if (src[i] == '\n') {
                ++line;
                col = 1;
            } else {
                ++col;
            }
        }
        return {line, col};
    }

    std::string getErrorContext(const std::string& src, size_t index, size_t contextLen) {
        size_t start = (index > contextLen) ? index - contextLen : 0;
        size_t end = std::min(index + contextLen, src.size());

        // Tìm đầu dòng
        while (start > 0 && src[start - 1] != '\n') --start;
        // Tìm cuối dòng
        while (end < src.size() && src[end] != '\n') ++end;

        std::string context = src.substr(start, end - start);
        // Thay thế các ký tự điều khiển
        for (char& c : context) {
            if (c == '\t') c = ' ';
            else if (c < 32 && c != '\n') c = '?';
        }
        return context;
    }

    // ==================== Core Lexer Functions ====================

    bool isNumber(const std::string &s) noexcept {
        if (s.empty()) return false;
        size_t start = (s[0] == '-') ? 1 : 0;
        return std::all_of(s.begin() + start, s.end(), [](unsigned char c) {
            return std::isdigit(c);
        });
    }

    const std::unordered_map<std::string,int>& operatorPrecedenceMap() noexcept {
        static const std::unordered_map<std::string,int> ops = {
            {"=",0},{"||",1},{"&&",2},{"==",3},{"!=",3},{"<",3},{">",3},{"<=",3},{">=",3},
            {"+",4},{"-",4},{"*",5},{"/",5},{"%",5}, {"!",6},
            {"++",7}
        };
        return ops;
    }

    bool isOperator(const std::string &tok) noexcept {
        const auto &m = operatorPrecedenceMap();
        return m.find(tok) != m.end();
    }

    bool isStringLiteral(const std::string &tk) noexcept {
        return tk.size() >= 2 && tk.front() == '"' && tk.back() == '"';
    }

    // Heuristic identifier check that tolerates UTF-8 bytes (simple & pragmatic)
    bool isVariable(const std::string &tok) noexcept {
        if (tok.empty()) return false;
        if (isStringLiteral(tok)) return false;
        if (isNumber(tok) || isOperator(tok)) return false;
        if (tok == "(" || tok == ")" || tok == "{" || tok == "}" || tok == ";" || tok == ",") return false;

        unsigned char first = static_cast<unsigned char>(tok[0]);
        // allow ascii letter or underscore or non-ascii (start of UTF-8)
        if (!std::isalpha(first) && tok[0] != '_' && first < 0x80) return false;

        for (unsigned char uc : tok) {
            if (uc == '_' ) continue;
            if (uc < 0x80) {
                if (!std::isalnum(uc)) return false;
            } else {
                // non-ascii byte: accept (assume valid UTF-8 sequence),
                // this is a permissive heuristic; a stricter implementation would validate UTF-8.
                continue;
            }
        }

        return true;
    }

    // Helper: lowercase ASCII characters (keep non-ascii unchanged)
    std::string toLowerAscii(const std::string &s) {
        std::string out;
        out.reserve(s.size());
        for (unsigned char c : s) {
            if (c < 0x80) out.push_back(static_cast<char>(std::tolower(c)));
            else out.push_back(static_cast<char>(c));
        }
        return out;
    }

    // Tokenize, with comment and improved string handling
    // Bổ sung: error handling cho các trường hợp ngoài mong đợi
    std::vector<std::string> tokenize(const std::string &src) {
        std::vector<std::string> tokens;
        size_t i = 0;
        const size_t n = src.size();
        while (i < n) {
            auto ch = static_cast<unsigned char>(src[i]);
            // whitespace
            if (std::isspace(ch)) { ++i; continue; }

            // comments: // line or /* block */
            if (ch == '/' && i + 1 < n) {
                unsigned char n1 = static_cast<unsigned char>(src[i+1]);
                if (n1 == '/') {
                    // skip until newline
                    i += 2;
                    while (i < n && src[i] != '\n') ++i;
                    continue;
                } else if (n1 == '*') {
                    // skip block comment
                    size_t commentStart = i;
                    i += 2;
                    bool closed = false;
                    while (i + 1 < n) {
                        if (src[i] == '*' && src[i+1] == '/') {
                            i += 2;
                            closed = true;
                            break;
                        }
                        ++i;
                    }
                    // Kiểm tra comment không đóng
                    if (!closed) {
                        auto [line, col] = getLineAndColumn(src, commentStart);
                        throw UnclosedCommentError(line, col);
                    }
                    continue;
                }
            }

            // String literal with escape handling (keep quotes in token)
            if (ch == '"' || ch == '\'') {
                char quote = static_cast<char>(ch);
                size_t stringStart = i;
                size_t j = i + 1;
                std::ostringstream oss;
                bool closed = false;
                while (j < n) {
                    char c = src[j];
                    if (c == '\\' && j + 1 < n) {
                        // escape sequence - validate and keep
                        char esc = src[j+1];
                        // Kiểm tra escape sequence hợp lệ (permissive mode - chỉ cảnh báo, không throw)
                        // Nếu muốn strict mode, bỏ comment dòng dưới:
                        // if (esc != 'n' && esc != 'r' && esc != 't' && esc != '\\' &&
                        //     esc != '\'' && esc != '"' && esc != '0') {
                        //     auto [line, col] = getLineAndColumn(src, j);
                        //     throw InvalidEscapeSequenceError(esc, line, col);
                        // }
                        oss.put('\\');
                        oss.put(esc);
                        j += 2;
                        continue;
                    }
                    if (c == quote) {
                        // include closing quote
                        ++j;
                        closed = true;
                        break;
                    }
                    // Kiểm tra newline không được phép trong chuỗi (trừ khi escaped)
                    if (c == '\n') {
                        auto [line, col] = getLineAndColumn(src, stringStart);
                        std::string partial = src.substr(stringStart + 1, std::min(j - stringStart - 1, (size_t)20));
                        throw UnclosedStringError(line, col, partial);
                    }
                    oss.put(c);
                    ++j;
                }
                // Kiểm tra chuỗi không đóng
                if (!closed) {
                    auto [line, col] = getLineAndColumn(src, stringStart);
                    std::string partial = src.substr(stringStart + 1, std::min(n - stringStart - 1, (size_t)20));
                    throw UnclosedStringError(line, col, partial);
                }
                std::string raw = src.substr(i, std::min(j, n) - i);
                tokens.push_back(raw);
                i = j;
                continue;
            }

            // two-char operators
            if (i + 1 < n) {
                std::string two = src.substr(i, 2);
                if (two == "==" || two == "!=" || two == "<=" || two == ">=" ||
                    two == "&&" || two == "||" || two == "++" || two == "--") {
                    tokens.push_back(two);
                    i += 2;
                    continue;
                }
            }

            // single-char punctuation/operators
            char c = src[i];
            if (c == '+' || c == '-' || c == '*' || c == '/' ||
                c == '(' || c == ')' || c == '{' || c == '}' ||
                c == '[' || c == ']' || c == ';' || c == ',' ||
                c == '<' || c == '>' || c == '=' || c == '!' || c == ':'
            ) {
                tokens.emplace_back(1, c);
                ++i;
                continue;
            }

            // identifier/number/word tokenization (UTF-8 friendly: read until separator)
            size_t j = i;
            while (j < n) {
                auto cj = static_cast<unsigned char>(src[j]);
                // stop at whitespace or any delimiter/punctuations we treat separately
                if (std::isspace(cj)) break;
                if (cj == '"' || cj == '+' || cj == '-' || cj == '*' || cj == '/' ||
                    cj == '(' || cj == ')' || cj == '{' || cj == '}' ||
                    cj == '[' || cj == ']' || cj == ';' || cj == ',' ||
                    cj == '<' || cj == '>' || cj == '=' || cj == '!' || cj == ':') break;
                ++j;
            }

            // Kiểm tra token rỗng (không nên xảy ra, nhưng phòng ngừa)
            if (j == i) {
                auto [line, col] = getLineAndColumn(src, i);
                throw InvalidCharacterError(src[i], line, col);
            }

            tokens.push_back(src.substr(i, j - i));
            i = j;
        }
        return tokens;
    }

    std::string normalizeTokenForCompare(const std::string& s) {
        std::string t = trim(s);
        if (t.empty()) return t;
        // If token is a quoted string, return as-is (do not modify inner content)
        if ( (t.size() >= 2 && t.front() == '"' && t.back() == '"') ||
             (t.size() >= 2 && t.front() == '\'' && t.back() == '\'') ) {
            return t;
        }
        // Remove trailing punctuation commonly attached to tokens
        char last = t.back();
        if (last == ':' || last == ';' || last == ',' || last == '.') {
            t.pop_back();
            t = trim(t);
            if (t.empty()) return t;
        }
        // Lowercase ASCII for comparison (keep non-ascii unchanged)
        return toLowerAscii(t);
    }

    std::vector<std::string> postProcessTokens(const std::vector<std::string>& tokens) {
        std::vector<std::string> result;
        result.reserve(tokens.size());

        // Danh sách các multi-word keywords (bằng token gốc, lower-case ASCII)
        // Nếu muốn mở rộng, thêm vào cả dạng có dấu và không dấu khi cần.
        const std::vector<std::vector<std::string>> multiKeywords = {
            {"mặc", "định"},
            {"mặc", "định:"},
            {"nếu", "không"},
            {"nếu", "không:"},
            {"trường", "hợp"},
            {"trường", "hợp:"}
            // thêm các cụm khác nếu cần
        };

        for (size_t i = 0; i < tokens.size(); ++i) {
            // Chuẩn bị phiên bản để so sánh (normalize) cho token hiện tại
            std::string a_norm = normalizeTokenForCompare(tokens[i]);

            bool matchedMulti = false;

            // Thử khớp các multi-word keywords (ưu tiên các cụm dài hơn nếu thêm)
            for (const auto &phrase : multiKeywords) {
                size_t len = phrase.size();
                if (i + len - 1 >= tokens.size()) continue;

                bool ok = true;
                for (size_t k = 0; k < len; ++k) {
                    std::string tk_norm = normalizeTokenForCompare(tokens[i + k]);
                    // so sánh chính xác với từng phần của phrase
                    // Note: phrase entries are expected to be already lower-cased ASCII-ish; we compare normalized forms
                    if (tk_norm != toLowerAscii(phrase[k])) { ok = false; break; }
                }
                if (ok) {
                    // Tạo token ghép (giữ dạng nối bằng space để tương thích)
                    std::ostringstream oss;
                    for (size_t k = 0; k < len; ++k) {
                        if (k) oss << ' ';
                        oss << phrase[k];
                    }
                    result.push_back(oss.str());
                    i += len - 1; // skip matched tokens
                    matchedMulti = true;
                    break;
                }
            }

            if (matchedMulti) continue;

            // Trường hợp token hiện tại đã là "mặc định" hoặc tương tự (đã normalize)
            if (!a_norm.empty()) {
                if (a_norm == "mặc định" || a_norm == "mặc định:") {
                    result.push_back("mặc định");
                    continue;
                }
            }

            // Giữ nguyên token gốc nếu không có xử lý đặc biệt
            result.push_back(tokens[i]);
        }

        return result;
    }

    std::string stripQuotes(const std::string& input) {
        if (input.length() >= 2 &&
            ((input.front() == '"' && input.back() == '"') ||
             (input.front() == '\'' && input.back() == '\''))) {
            // Process escape sequences inside when returning stripped content
            std::string inner = input.substr(1, input.length() - 2);
            std::ostringstream oss;
            for (size_t i = 0; i < inner.size(); ++i) {
                if (inner[i] == '\\' && i + 1 < inner.size()) {
                    char esc = inner[i+1];
                    switch (esc) {
                        case 'n': oss.put('\n'); break;
                        case 'r': oss.put('\r'); break;
                        case 't': oss.put('\t'); break;
                        case '\\': oss.put('\\'); break;
                        case '\'': oss.put('\''); break;
                        case '"': oss.put('"'); break;
                        case '0': oss.put('\0'); break;
                        default:
                            // Escape không được nhận diện - cảnh báo hoặc giữ nguyên
                            // Có thể throw InvalidEscapeSequenceError nếu muốn strict mode
                            oss.put(esc);
                            break;
                    }
                    ++i; // skip escape char
                } else {
                    oss.put(inner[i]);
                }
            }
            return oss.str();
        }
        return input;
    }

    int getVarValueInt(int varId) {
        if (varId < 0 || static_cast<size_t>(varId) >= vars.size()) {
            throw std::runtime_error("getVarValueInt: varId ngoài phạm vi (id=" + std::to_string(varId) +
                                     ", size=" + std::to_string(vars.size()) + ")");
        }
        const Value& v = vars[varId];
        if (std::holds_alternative<int>(v)) {
            return std::get<int>(v);
        }
        // nếu là chuỗi, thử chuyển sang int; nếu không parse được thì lỗi
        if (std::holds_alternative<std::string>(v)) {
            const std::string& strVal = std::get<std::string>(v);
            try {
                return std::stoi(strVal);
            } catch (const std::invalid_argument&) {
                throw std::runtime_error("getVarValueInt: giá trị biến không phải số hợp lệ: '" + strVal + "'");
            } catch (const std::out_of_range&) {
                throw std::runtime_error("getVarValueInt: giá trị số quá lớn: '" + strVal + "'");
            }
        }
        throw std::runtime_error("getVarValueInt: kiểu giá trị không hỗ trợ");
    }

    // ==================== Validation Functions Implementation ====================

    void validateNumber(const std::string& token, size_t line, size_t column) {
        if (token.empty()) {
            throw InvalidNumberError(token, line, column);
        }

        size_t start = 0;
        if (token[0] == '-' || token[0] == '+') {
            start = 1;
            if (token.size() == 1) {
                throw InvalidNumberError(token, line, column);
            }
        }

        bool hasDecimal = false;
        for (size_t i = start; i < token.size(); ++i) {
            if (token[i] == '.') {
                if (hasDecimal) {
                    throw InvalidNumberError(token, line, column);
                }
                hasDecimal = true;
            } else if (!std::isdigit(static_cast<unsigned char>(token[i]))) {
                throw InvalidNumberError(token, line, column);
            }
        }
    }

    void validateIdentifier(const std::string& token, size_t line, size_t column) {
        if (token.empty()) {
            throw LexerError("Tên định danh không được rỗng", line, column, "");
        }

        unsigned char first = static_cast<unsigned char>(token[0]);
        // Phải bắt đầu bằng chữ cái, underscore, hoặc ký tự UTF-8
        if (std::isdigit(first)) {
            throw InvalidIdentifierError(token, line, column);
        }
    }

    void validateStringLiteral(const std::string& token, size_t line, size_t column) {
        if (token.size() < 2) {
            throw LexerError("Chuỗi không hợp lệ: '" + token + "'", line, column, "");
        }

        char openQuote = token.front();
        char closeQuote = token.back();

        if ((openQuote != '"' && openQuote != '\'') || openQuote != closeQuote) {
            throw LexerError("Chuỗi không được đóng đúng cách: '" + token + "'", line, column, "");
        }
    }

} // namespace vietvm::compiler

// Created by nx_thang on 10/20/2025.
// Updated: bổ sung hỗ trợ comment, escape trong string, cải thiện nhận diện identifier UTF-8,
// and ổn định post-processing multi-word keywords.
// Updated: thêm error handling và exception cho các trường hợp ngoài mong đợi.

#include <algorithm>
#include <cctype>
#include <sstream>
#include <stdexcept>
#include <variant>
#include <string>
#include <unordered_map>

#include "../../include/frontend/lexer.h"
#include "common/utility.h"

namespace vietvm::compiler {
    using Value = std::variant<int, std::string>;
    std::vector<Value> vars; // indexed by varId

    // ==================== Helper Functions Implementation ====================

    std::pair<size_t, size_t> getLineAndColumn(const std::string& src, size_t index) {
        size_t line = 1;
        size_t col = 1;
        for (size_t i = 0; i < index && i < src.size(); ++i) {
            if (src[i] == '\n') {
                ++line;
                col = 1;
            } else {
                ++col;
            }
        }
        return {line, col};
    }

    std::string getErrorContext(const std::string& src, size_t index, size_t contextLen) {
        size_t start = (index > contextLen) ? index - contextLen : 0;
        size_t end = std::min(index + contextLen, src.size());

        // Tìm đầu dòng
        while (start > 0 && src[start - 1] != '\n') --start;
        // Tìm cuối dòng
        while (end < src.size() && src[end] != '\n') ++end;

        std::string context = src.substr(start, end - start);
        // Thay thế các ký tự điều khiển
        for (char& c : context) {
            if (c == '\t') c = ' ';
            else if (c < 32 && c != '\n') c = '?';
        }
        return context;
    }

    // ==================== Core Lexer Functions ====================

    bool isNumber(const std::string &s) noexcept {
        if (s.empty()) return false;
        size_t start = (s[0] == '-') ? 1 : 0;
        return std::all_of(s.begin() + start, s.end(), [](unsigned char c) {
            return std::isdigit(c);
        });
    }

    const std::unordered_map<std::string,int>& operatorPrecedenceMap() noexcept {
        static const std::unordered_map<std::string,int> ops = {
            {"=",0},{"||",1},{"&&",2},{"==",3},{"!=",3},{"<",3},{">",3},{"<=",3},{">=",3},
            {"+",4},{"-",4},{"*",5},{"/",5},{"%",5}, {"!",6},
            {"++",7}
        };
        return ops;
    }

    bool isOperator(const std::string &tok) noexcept {
        const auto &m = operatorPrecedenceMap();
        return m.find(tok) != m.end();
    }

    bool isStringLiteral(const std::string &tk) noexcept {
        if (tk.size() < 2) return false;
        // Accept both double quotes ("...") and single quotes ('...')
        return (tk.front() == '"' && tk.back() == '"') ||
               (tk.front() == '\'' && tk.back() == '\'');
    }

    // Heuristic identifier check that tolerates UTF-8 bytes (simple & pragmatic)
    bool isVariable(const std::string &tok) noexcept {
        if (tok.empty()) return false;
        if (isStringLiteral(tok)) return false;
        if (isNumber(tok) || isOperator(tok)) return false;
        if (tok == "(" || tok == ")" || tok == "{" || tok == "}" || tok == ";" || tok == ",") return false;

        unsigned char first = static_cast<unsigned char>(tok[0]);
        // allow ascii letter or underscore or non-ascii (start of UTF-8)
        if (!std::isalpha(first) && tok[0] != '_' && first < 0x80) return false;

        for (unsigned char uc : tok) {
            if (uc == '_' ) continue;
            if (uc < 0x80) {
                if (!std::isalnum(uc)) return false;
            } else {
                // non-ascii byte: accept (assume valid UTF-8 sequence),
                // this is a permissive heuristic; a stricter implementation would validate UTF-8.
                continue;
            }
        }

        return true;
    }

    // Helper: lowercase ASCII characters (keep non-ascii unchanged)
    std::string toLowerAscii(const std::string &s) {
        std::string out;
        out.reserve(s.size());
        for (unsigned char c : s) {
            if (c < 0x80) out.push_back(static_cast<char>(std::tolower(c)));
            else out.push_back(static_cast<char>(c));
        }
        return out;
    }

    // Tokenize, with comment and improved string handling
    // Bổ sung: error handling cho các trường hợp ngoài mong đợi
    std::vector<std::string> tokenize(const std::string &src) {
        std::vector<std::string> tokens;
        size_t i = 0;
        const size_t n = src.size();
        while (i < n) {
            auto ch = static_cast<unsigned char>(src[i]);
            // whitespace
            if (std::isspace(ch)) { ++i; continue; }

            // comments: // line or /* block */
            if (ch == '/' && i + 1 < n) {
                unsigned char n1 = static_cast<unsigned char>(src[i+1]);
                if (n1 == '/') {
                    // skip until newline
                    i += 2;
                    while (i < n && src[i] != '\n') ++i;
                    continue;
                } else if (n1 == '*') {
                    // skip block comment
                    size_t commentStart = i;
                    i += 2;
                    bool closed = false;
                    while (i + 1 < n) {
                        if (src[i] == '*' && src[i+1] == '/') {
                            i += 2;
                            closed = true;
                            break;
                        }
                        ++i;
                    }
                    // Kiểm tra comment không đóng
                    if (!closed) {
                        auto [line, col] = getLineAndColumn(src, commentStart);
                        throw UnclosedCommentError(line, col);
                    }
                    continue;
                }
            }

            // String literal with escape handling (keep quotes in token)
            if (ch == '"' || ch == '\'') {
                char quote = static_cast<char>(ch);
                size_t stringStart = i;
                size_t j = i + 1;
                std::ostringstream oss;
                bool closed = false;
                while (j < n) {
                    char c = src[j];
                    if (c == '\\' && j + 1 < n) {
                        // escape sequence - validate and keep
                        char esc = src[j+1];
                        // Kiểm tra escape sequence hợp lệ (permissive mode - chỉ cảnh báo, không throw)
                        // Nếu muốn strict mode, bỏ comment dòng dưới:
                        // if (esc != 'n' && esc != 'r' && esc != 't' && esc != '\\' &&
                        //     esc != '\'' && esc != '"' && esc != '0') {
                        //     auto [line, col] = getLineAndColumn(src, j);
                        //     throw InvalidEscapeSequenceError(esc, line, col);
                        // }
                        oss.put('\\');
                        oss.put(esc);
                        j += 2;
                        continue;
                    }
                    if (c == quote) {
                        // include closing quote
                        ++j;
                        closed = true;
                        break;
                    }
                    // Kiểm tra newline không được phép trong chuỗi (trừ khi escaped)
                    if (c == '\n') {
                        auto [line, col] = getLineAndColumn(src, stringStart);
                        std::string partial = src.substr(stringStart + 1, std::min(j - stringStart - 1, (size_t)20));
                        throw UnclosedStringError(line, col, partial);
                    }
                    oss.put(c);
                    ++j;
                }
                // Kiểm tra chuỗi không đóng
                if (!closed) {
                    auto [line, col] = getLineAndColumn(src, stringStart);
                    std::string partial = src.substr(stringStart + 1, std::min(n - stringStart - 1, (size_t)20));
                    throw UnclosedStringError(line, col, partial);
                }
                std::string raw = src.substr(i, std::min(j, n) - i);
                tokens.push_back(raw);
                i = j;
                continue;
            }

            // two-char operators
            if (i + 1 < n) {
                std::string two = src.substr(i, 2);
                if (two == "==" || two == "!=" || two == "<=" || two == ">=" ||
                    two == "&&" || two == "||" || two == "++" || two == "--") {
                    tokens.push_back(two);
                    i += 2;
                    continue;
                }
            }

            // single-char punctuation/operators
            char c = src[i];
            if (c == '+' || c == '-' || c == '*' || c == '/' ||
                c == '(' || c == ')' || c == '{' || c == '}' ||
                c == '[' || c == ']' || c == ';' || c == ',' ||
                c == '<' || c == '>' || c == '=' || c == '!' || c == ':'
            ) {
                tokens.emplace_back(1, c);
                ++i;
                continue;
            }

            // identifier/number/word tokenization (UTF-8 friendly: read until separator)
            size_t j = i;
            while (j < n) {
                auto cj = static_cast<unsigned char>(src[j]);
                // stop at whitespace or any delimiter/punctuations we treat separately
                if (std::isspace(cj)) break;
                if (cj == '"' || cj == '+' || cj == '-' || cj == '*' || cj == '/' ||
                    cj == '(' || cj == ')' || cj == '{' || cj == '}' ||
                    cj == '[' || cj == ']' || cj == ';' || cj == ',' ||
                    cj == '<' || cj == '>' || cj == '=' || cj == '!' || cj == ':') break;
                ++j;
            }

            // Kiểm tra token rỗng (không nên xảy ra, nhưng phòng ngừa)
            if (j == i) {
                auto [line, col] = getLineAndColumn(src, i);
                throw InvalidCharacterError(src[i], line, col);
            }

            tokens.push_back(src.substr(i, j - i));
            i = j;
        }
        return tokens;
    }

    std::string normalizeTokenForCompare(const std::string& s) {
        std::string t = trim(s);
        if (t.empty()) return t;
        // If token is a quoted string, return as-is (do not modify inner content)
        if ( (t.size() >= 2 && t.front() == '"' && t.back() == '"') ||
             (t.size() >= 2 && t.front() == '\'' && t.back() == '\'') ) {
            return t;
        }
        // Remove trailing punctuation commonly attached to tokens
        char last = t.back();
        if (last == ':' || last == ';' || last == ',' || last == '.') {
            t.pop_back();
            t = trim(t);
            if (t.empty()) return t;
        }
        // Lowercase ASCII for comparison (keep non-ascii unchanged)
        return toLowerAscii(t);
    }

    std::vector<std::string> postProcessTokens(const std::vector<std::string>& tokens) {
        std::vector<std::string> result;
        result.reserve(tokens.size());

        // Danh sách các multi-word keywords (bằng token gốc, lower-case ASCII)
        // Nếu muốn mở rộng, thêm vào cả dạng có dấu và không dấu khi cần.
        const std::vector<std::vector<std::string>> multiKeywords = {
            {"mặc", "định"},
            {"mặc", "định:"},
            {"nếu", "không"},
            {"nếu", "không:"},
            {"trường", "hợp"},
            {"trường", "hợp:"}
            // thêm các cụm khác nếu cần
        };

        for (size_t i = 0; i < tokens.size(); ++i) {
            // Chuẩn bị phiên bản để so sánh (normalize) cho token hiện tại
            std::string a_norm = normalizeTokenForCompare(tokens[i]);

            bool matchedMulti = false;

            // Thử khớp các multi-word keywords (ưu tiên các cụm dài hơn nếu thêm)
            for (const auto &phrase : multiKeywords) {
                size_t len = phrase.size();
                if (i + len - 1 >= tokens.size()) continue;

                bool ok = true;
                for (size_t k = 0; k < len; ++k) {
                    std::string tk_norm = normalizeTokenForCompare(tokens[i + k]);
                    // so sánh chính xác với từng phần của phrase
                    // Note: phrase entries are expected to be already lower-cased ASCII-ish; we compare normalized forms
                    if (tk_norm != toLowerAscii(phrase[k])) { ok = false; break; }
                }
                if (ok) {
                    // Tạo token ghép (giữ dạng nối bằng space để tương thích)
                    std::ostringstream oss;
                    for (size_t k = 0; k < len; ++k) {
                        if (k) oss << ' ';
                        oss << phrase[k];
                    }
                    result.push_back(oss.str());
                    i += len - 1; // skip matched tokens
                    matchedMulti = true;
                    break;
                }
            }

            if (matchedMulti) continue;

            // Trường hợp token hiện tại đã là "mặc định" hoặc tương tự (đã normalize)
            if (!a_norm.empty()) {
                if (a_norm == "mặc định" || a_norm == "mặc định:") {
                    result.push_back("mặc định");
                    continue;
                }
            }

            // Giữ nguyên token gốc nếu không có xử lý đặc biệt
            result.push_back(tokens[i]);
        }

        return result;
    }

    std::string stripQuotes(const std::string& input) {
        if (input.length() >= 2 &&
            ((input.front() == '"' && input.back() == '"') ||
             (input.front() == '\'' && input.back() == '\''))) {
            // Process escape sequences inside when returning stripped content
            std::string inner = input.substr(1, input.length() - 2);
            std::ostringstream oss;
            for (size_t i = 0; i < inner.size(); ++i) {
                if (inner[i] == '\\' && i + 1 < inner.size()) {
                    char esc = inner[i+1];
                    switch (esc) {
                        case 'n': oss.put('\n'); break;
                        case 'r': oss.put('\r'); break;
                        case 't': oss.put('\t'); break;
                        case '\\': oss.put('\\'); break;
                        case '\'': oss.put('\''); break;
                        case '"': oss.put('"'); break;
                        case '0': oss.put('\0'); break;
                        default:
                            // Escape không được nhận diện - cảnh báo hoặc giữ nguyên
                            // Có thể throw InvalidEscapeSequenceError nếu muốn strict mode
                            oss.put(esc);
                            break;
                    }
                    ++i; // skip escape char
                } else {
                    oss.put(inner[i]);
                }
            }
            return oss.str();
        }
        return input;
    }

    int getVarValueInt(int varId) {
        if (varId < 0 || static_cast<size_t>(varId) >= vars.size()) {
            throw std::runtime_error("getVarValueInt: varId ngoài phạm vi (id=" + std::to_string(varId) +
                                     ", size=" + std::to_string(vars.size()) + ")");
        }
        const Value& v = vars[varId];
        if (std::holds_alternative<int>(v)) {
            return std::get<int>(v);
        }
        // nếu là chuỗi, thử chuyển sang int; nếu không parse được thì lỗi
        if (std::holds_alternative<std::string>(v)) {
            const std::string& strVal = std::get<std::string>(v);
            try {
                return std::stoi(strVal);
            } catch (const std::invalid_argument&) {
                throw std::runtime_error("getVarValueInt: giá trị biến không phải số hợp lệ: '" + strVal + "'");
            } catch (const std::out_of_range&) {
                throw std::runtime_error("getVarValueInt: giá trị số quá lớn: '" + strVal + "'");
            }
        }
        throw std::runtime_error("getVarValueInt: kiểu giá trị không hỗ trợ");
    }

    // ==================== Validation Functions Implementation ====================

    void validateNumber(const std::string& token, size_t line, size_t column) {
        if (token.empty()) {
            throw InvalidNumberError(token, line, column);
        }

        size_t start = 0;
        if (token[0] == '-' || token[0] == '+') {
            start = 1;
            if (token.size() == 1) {
                throw InvalidNumberError(token, line, column);
            }
        }

        bool hasDecimal = false;
        for (size_t i = start; i < token.size(); ++i) {
            if (token[i] == '.') {
                if (hasDecimal) {
                    throw InvalidNumberError(token, line, column);
                }
                hasDecimal = true;
            } else if (!std::isdigit(static_cast<unsigned char>(token[i]))) {
                throw InvalidNumberError(token, line, column);
            }
        }
    }

    void validateIdentifier(const std::string& token, size_t line, size_t column) {
        if (token.empty()) {
            throw LexerError("Tên định danh không được rỗng", line, column, "");
        }

        unsigned char first = static_cast<unsigned char>(token[0]);
        // Phải bắt đầu bằng chữ cái, underscore, hoặc ký tự UTF-8
        if (std::isdigit(first)) {
            throw InvalidIdentifierError(token, line, column);
        }
    }

    void validateStringLiteral(const std::string& token, size_t line, size_t column) {
        if (token.size() < 2) {
            throw LexerError("Chuỗi không hợp lệ: '" + token + "'", line, column, "");
        }

        char openQuote = token.front();
        char closeQuote = token.back();

        if ((openQuote != '"' && openQuote != '\'') || openQuote != closeQuote) {
            throw LexerError("Chuỗi không được đóng đúng cách: '" + token + "'", line, column, "");
        }
    }

} // namespace vietvm::compiler

#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <filesystem>
#include "../../include/compiler/compiler.h"
#include "../../include/vm/vm.h"
#include "../../include/frontend/keywords.h"
#include "common/storeString.h"
#include "../../include/compiler/compileRegistry.h"

namespace fs = std::filesystem;

std::string readFile(const std::string &filename) {
    std::ifstream fileStream(filename);
    if (!fileStream.is_open()) {
        throw std::runtime_error("Không thể mở file: " + filename);
    }
    std::stringstream buffer;
    buffer << fileStream.rdbuf();
    return buffer.str();
}


int main(int argc, char* argv[]) {
    try {
        initCompileMap();

        // -----------------------------
        // Trường hợp có đối số (chạy file được chỉ định)
        // -----------------------------
        if (argc == 2) {
            const std::string filename = argv[1];
            std::string source = readFile(filename);

            // Ensure relative imports inside the compiled file resolve relative to the file's directory
            // Use RAII-style guard to always restore cwd even on exception
            auto prev_cwd = fs::current_path();
            struct CwdGuard {
                fs::path saved;
                explicit CwdGuard(fs::path p) : saved(std::move(p)) {}
                ~CwdGuard() { try { fs::current_path(saved); } catch(...) {} }
            } cwdGuard(prev_cwd);

            if (!fs::path(filename).parent_path().empty()) {
                fs::current_path(fs::path(filename).parent_path());
            }

            vietvm::compiler::StringPool::clear();
            // Reset imported files tracking between compilations
            vietvm::compiler::clearImportedFiles();
            vietvm::compiler::hamMap::hamBytecodeMap.clear();
            vietvm::compiler::hamMap::clearHamNameIndexMap();
            vietvm::compiler::hamMap::resetHamIdCounter();
            std::vector<Instruction> bytecode = compileSource(source, keywordMap);
            // cwd will be restored by CwdGuard destructor

            const auto& stringPool = vietvm::compiler::StringPool::getPool();
            VM vm(bytecode, stringPool);

            // <-- ADD: copy compiled functions into VM so OP_GOI can find them
            vm.hamBytecodeMap = vietvm::compiler::hamMap::hamBytecodeMap;

            vm.run();

            return EXIT_SUCCESS;
        }

        // -----------------------------
        // Nếu không có đối số → chạy file mặc định
        // -----------------------------
        const std::string defaultFile = "../../src/tests/import_main.vi";
        if (argc == 1 && fs::exists(defaultFile)) {
            std::string source = readFile(defaultFile);

            // run default file with cwd set to its parent so imports resolve
            // Use RAII-style guard to always restore cwd even on exception
            auto prev_cwd = fs::current_path();
            struct CwdGuard {
                fs::path saved;
                explicit CwdGuard(fs::path p) : saved(std::move(p)) {}
                ~CwdGuard() { try { fs::current_path(saved); } catch(...) {} }
            } cwdGuard(prev_cwd);

            if (!fs::path(defaultFile).parent_path().empty()) {
                fs::current_path(fs::path(defaultFile).parent_path());
            }

            vietvm::compiler::StringPool::clear();
            // Reset imported files tracking between compilations
            vietvm::compiler::clearImportedFiles();
            vietvm::compiler::hamMap::hamBytecodeMap.clear();
            vietvm::compiler::hamMap::clearHamNameIndexMap();
            vietvm::compiler::hamMap::resetHamIdCounter();

            std::vector<Instruction> bytecode = compileSource(source, keywordMap);
            // cwd will be restored by CwdGuard destructor
            const auto& stringPool = vietvm::compiler::StringPool::getPool();

            // In bytecode để debug
            std::cout << "=> Danh sách bytecode cho file mã nguồn (" << defaultFile << "):" << std::endl;
            for (size_t i = 0; i < bytecode.size(); ++i) {
                const Instruction &instr = bytecode[i];
                std::cout << "[" << i << "] "
                          << "op: " << instr.op << " (" << name_op(instr.op) << ")";
                if (instr.operandIndex != -1)
                    std::cout << ", operandIndex: " << instr.operandIndex;
                if (instr.operand != 0)
                    std::cout << ", operand: " << instr.operand;
                std::cout << std::endl;
            }
            VM vm(bytecode, stringPool);

            // copy compiled functions into VM
            vm.hamBytecodeMap = vietvm::compiler::hamMap::hamBytecodeMap;
            vm.run();
            return EXIT_SUCCESS;
        }

        std::string testDir = "../../src/tests";
        if (fs::exists(testDir)) {
            for (const auto& entry : fs::directory_iterator(testDir)) {
                if (entry.path().extension() == ".vi") {
                    const std::string filename = entry.path().string();
                    std::cout << "\n Đang chạy test: " << filename << std::endl;

                    std::string source = readFile(filename);
                    // Ensure imports inside each test file resolve relative to the test file location
                    auto prev_cwd = fs::current_path();
                    if (!fs::path(filename).parent_path().empty()) {
                        fs::current_path(fs::path(filename).parent_path());
                    }
                    vietvm::compiler::StringPool::clear();
                    // Reset imported files tracking between compilations
                    vietvm::compiler::clearImportedFiles();
                    std::vector<Instruction> bytecode = compileSource(source, keywordMap);
                    fs::current_path(prev_cwd);
                    const auto& stringPool = vietvm::compiler::StringPool::getPool();

                    VM vm(bytecode, stringPool);
                    // copy compiled functions into VM
                    vm.hamBytecodeMap = vietvm::compiler::hamMap::hamBytecodeMap;
                    vm.run();
                }
            }
        } else {
            std::cerr << "Thư mục tests/ không tồn tại.\n";
        }

    } catch (const std::exception &ex) {
        std::cerr << "Lỗi: " << ex.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

